umask-permisos:
cat > /home/learner/aso/p13/umask-permisos.sh <<'ASO_EOF'
#!/bin/bash
(($#!=1)) && { echo "uso: umask-permisos.sh MASCARA" >&2; exit 1; }
[[ ! $1 =~ ^[0-7]{3}$ ]] && { echo "máscara no válida" >&2; exit 2; }
printf 'fichero: %03o\n' $((8#666 & ~8#$1))
printf 'directorio: %03o\n' $((8#777 & ~8#$1))
exit 0
ASO_EOF
chmod 755 /home/learner/aso/p13/umask-permisos.sh
chown learner:learner /home/learner/aso/p13/umask-permisos.sh

especiales:
cat > /home/learner/aso/p13/especiales.sh <<'ASO_EOF'
#!/bin/bash
error() { echo "$1" >&2; exit "$2"; }
(($#!=2)) && error "uso: especiales.sh -u|-g DIRECTORIO" 1
case $1 in
  -u) bit=4000;;
  -g) bit=2000;;
  *) error "opción no válida" 2;;
esac
[[ ! -d $2 ]] && error "no es un directorio" 4
lista=$(find "$2" -maxdepth 1 -type f -perm -$bit 2>/dev/null | sort)
echo "${lista:-ninguno}"
exit 0
ASO_EOF
chmod 755 /home/learner/aso/p13/especiales.sh
chown learner:learner /home/learner/aso/p13/especiales.sh
